WITH valid AS (SELECT *, LOWER(dept_name) AS dept_name_lower, TRIM(dept_name) AS clean_dept_name, COALESCE(location, 'NONE') AS resolved_location FROM departments WHERE dept_name IS NOT NULL AND dept_name NOT IN ('Finance', 'Sales')) SELECT s.*, latest.employee_hire_date FROM valid s JOIN LATERAL (SELECT c.hire_date AS employee_hire_date FROM employees c WHERE c.dept_id = s.id ORDER BY c.salary DESC, c.id DESC LIMIT 1) latest ON TRUE;
